package com.salesforce.androidsdk.mobilesync.target

import androidx.test.ext.junit.runners.AndroidJUnit4
import androidx.test.filters.SmallTest
import com.salesforce.androidsdk.mobilesync.manager.SyncManagerTestCase
import com.salesforce.androidsdk.mobilesync.util.Constants
import com.salesforce.androidsdk.mobilesync.util.SyncOptions
import com.salesforce.androidsdk.mobilesync.util.SyncState.MergeMode
import org.json.JSONObject
import org.junit.After
import org.junit.Assert
import org.junit.Before
import org.junit.Test
import org.junit.runner.RunWith
import java.util.Arrays

@RunWith(AndroidJUnit4::class)
@SmallTest
open class SyncUpTargetTest : SyncManagerTestCase() {
    companion object { protected const val COUNT_TEST_ACCOUNTS = 10 }
    protected lateinit var idToFields: MutableMap<String, Map<String, Any>>

    @Before override fun setUp() { super.setUp(); createAccountsSoup(); idToFields = createRecordsOnServerReturnFields(COUNT_TEST_ACCOUNTS, Constants.ACCOUNT, null) }
    @After override fun tearDown() { deleteRecordsByIdOnServer(idToFields.keys, Constants.ACCOUNT); dropAccountsSoup(); super.tearDown() }

    @Test fun testSyncUpWithUpdateFieldList() { trySyncDown(MergeMode.OVERWRITE); val idToFieldsLocallyUpdated = makeLocalChanges(idToFields, ACCOUNTS_SOUP); trySyncUp(idToFieldsLocallyUpdated.size, MergeMode.OVERWRITE, null, listOf(Constants.NAME)); checkDbStateFlags(idToFieldsLocallyUpdated.keys, false, false, false, ACCOUNTS_SOUP); val idToFieldsExpectedOnServer = HashMap<String, Map<String, Any>>(); for (id in idToFieldsLocallyUpdated.keys) { val expectedFields = HashMap<String, Any>(); expectedFields[Constants.NAME] = idToFieldsLocallyUpdated[id]!![Constants.NAME]!!; expectedFields[Constants.DESCRIPTION] = idToFields[id]!![Constants.DESCRIPTION]!!; idToFieldsExpectedOnServer[id] = expectedFields }; checkServer(idToFieldsExpectedOnServer, Constants.ACCOUNT) }
    @Test fun testSyncUpWithCreateFieldList() { val names = arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)); createAccountsLocally(names); trySyncUp(3, MergeMode.OVERWRITE, listOf(Constants.NAME), null); val idToFieldsCreated = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, names); checkDbStateFlags(idToFieldsCreated.keys, false, false, false, ACCOUNTS_SOUP); val idToFieldsExpectedOnServer = HashMap<String, Map<String, Any>>(); for (id in idToFieldsCreated.keys) { val expectedFields = HashMap<String, Any>(); expectedFields[Constants.NAME] = idToFieldsCreated[id]!![Constants.NAME]!!; expectedFields[Constants.DESCRIPTION] = JSONObject.NULL; idToFieldsExpectedOnServer[id] = expectedFields }; checkServer(idToFieldsExpectedOnServer, Constants.ACCOUNT); idToFields.putAll(idToFieldsCreated) }
    @Test fun testSyncUpWithErrors() { val buffer = StringBuilder(256); for (i in 0 until 256) buffer.append("x"); val nameTooLong = buffer.toString(); val goodNames = arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)); val badNames = arrayOf(nameTooLong, ""); createAccountsLocally(goodNames); createAccountsLocally(badNames); trySyncUp(5, MergeMode.OVERWRITE); val idToFieldsGoodNames = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, goodNames); checkDbStateFlags(idToFieldsGoodNames.keys, false, false, false, ACCOUNTS_SOUP); val idToFieldsBadNames = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION, SyncTarget.LAST_ERROR), Constants.NAME, badNames); checkDbStateFlags(idToFieldsBadNames.keys, true, false, false, ACCOUNTS_SOUP); for (fields in idToFieldsBadNames.values) { val name = fields[Constants.NAME] as String; val lastError = fields[SyncTarget.LAST_ERROR] as String; if (name == nameTooLong) { Assert.assertTrue("Name too large error expected", lastError.contains("Account Name: data value too large")) } else if (name == "") { Assert.assertTrue("Missing name error expected", lastError.contains("Required fields are missing: [Name]")) } else { Assert.fail("Unexpected record found: $name") } }; checkServer(idToFieldsGoodNames, Constants.ACCOUNT); idToFields.putAll(idToFieldsGoodNames) }
    @Test fun testSyncUpWithNoType() { trySyncUpBadTypeOrNoType(true) }
    @Test fun testSyncUpWithBadType() { trySyncUpBadTypeOrNoType(false) }
    private fun trySyncUpBadTypeOrNoType(noType: Boolean) { val namesGoodRecords = arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)); val namesBadRecords = arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)); val setNamesBadRecords = HashSet(namesBadRecords.toList()); createAccountsLocally(namesGoodRecords); createAccountsLocally(namesBadRecords, object : Mutator { override fun mutate(record: JSONObject): JSONObject { if (noType) { record.remove(Constants.ATTRIBUTES) } else { val attributes = JSONObject(); attributes.put(TYPE, "badType"); record.put(Constants.ATTRIBUTES, attributes) }; return record } }); trySyncUp(5, MergeMode.OVERWRITE); val idToFieldsGoodNames = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, namesGoodRecords); checkDbStateFlags(idToFieldsGoodNames.keys, false, false, false, ACCOUNTS_SOUP); val idToFieldsBadNames = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION, SyncTarget.LAST_ERROR), Constants.NAME, namesBadRecords); checkDbStateFlags(idToFieldsBadNames.keys, true, false, false, ACCOUNTS_SOUP); Assert.assertEquals("Wrong number of bad records found", namesBadRecords.size, idToFieldsBadNames.size); for (fields in idToFieldsBadNames.values) { val name = fields[Constants.NAME] as String; val lastError = fields[SyncTarget.LAST_ERROR] as String; if (setNamesBadRecords.contains(name)) { Assert.assertTrue("Wrong error: $lastError", lastError.contains("The requested resource does not exist") || lastError.contains("sObject type 'badType' is not supported.") || lastError.contains("sObject type 'null' is not supported.")) } else { Assert.fail("Unexpected record found: $name") } }; checkServer(idToFieldsGoodNames, Constants.ACCOUNT); idToFields.putAll(idToFieldsGoodNames) }
    @Test fun testSyncUpWithLocallyUpdatedRecords() { trySyncDown(MergeMode.OVERWRITE); val idToFieldsLocallyUpdated = makeLocalChanges(idToFields, ACCOUNTS_SOUP); trySyncUp(3, MergeMode.OVERWRITE); checkDbStateFlags(idToFieldsLocallyUpdated.keys, false, false, false, ACCOUNTS_SOUP); checkServer(idToFieldsLocallyUpdated, Constants.ACCOUNT) }
    @Test fun testSyncUpWithLocallyUpdatedRemotelyUpdatedRecordsWithoutOverwrite() { trySyncDown(MergeMode.LEAVE_IF_CHANGED); val idToFieldsLocallyUpdated = makeLocalChanges(idToFields, ACCOUNTS_SOUP); Thread.sleep(1000); val idToFieldsRemotelyUpdated = HashMap<String, Map<String, Any>>(); val ids = idToFieldsLocallyUpdated.keys; for (id in ids) { val fields = idToFieldsLocallyUpdated[id]!!; val updatedFields = HashMap<String, Any>(); for (fieldName in fields.keys) { updatedFields[fieldName] = fields[fieldName].toString() + "_updated_again" }; idToFieldsRemotelyUpdated[id] = updatedFields }; updateRecordsOnServer(idToFieldsRemotelyUpdated, Constants.ACCOUNT); trySyncUp(3, MergeMode.LEAVE_IF_CHANGED); checkDbStateFlags(ids, false, true, false, ACCOUNTS_SOUP); checkServer(idToFieldsRemotelyUpdated, Constants.ACCOUNT); trySyncUp(3, MergeMode.OVERWRITE); checkDbStateFlags(ids, false, false, false, ACCOUNTS_SOUP); checkServer(idToFieldsLocallyUpdated, Constants.ACCOUNT) }
    @Test fun testSyncUpWithLocallyCreatedRecords() { trySyncUpWithLocallyCreatedRecords(3, MergeMode.OVERWRITE) }
    @Test fun testSyncUpWithLocallyCreatedRecordsWithoutOverwrite() { trySyncUpWithLocallyCreatedRecords(3, MergeMode.LEAVE_IF_CHANGED) }
    private fun trySyncUpWithLocallyCreatedRecords(countRecords: Int, syncUpMergeMode: MergeMode) { val listNames = ArrayList<String>(); for (i in 0 until countRecords) { listNames.add(createRecordName(Constants.ACCOUNT)) }; val names = listNames.toTypedArray(); createAccountsLocally(names); trySyncUp(countRecords, syncUpMergeMode); val idToFieldsCreated = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, names); checkDbStateFlags(idToFieldsCreated.keys, false, false, false, ACCOUNTS_SOUP); checkServer(idToFieldsCreated, Constants.ACCOUNT); idToFields.putAll(idToFieldsCreated) }
    @Test fun testSyncUpWithLocallyDeletedRecords() { trySyncDown(MergeMode.OVERWRITE); val allIds = idToFields.keys.toTypedArray(); val idsLocallyDeleted = arrayOf(allIds[0], allIds[1], allIds[2]); deleteRecordsLocally(ACCOUNTS_SOUP, *idsLocallyDeleted); trySyncUp(3, MergeMode.OVERWRITE); checkDbDeleted(ACCOUNTS_SOUP, idsLocallyDeleted, Constants.ID); checkServerDeleted(idsLocallyDeleted, Constants.ACCOUNT) }
    @Test fun testSyncUpWithLocallyCreatedAndDeletedRecords() { val names = arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)); createAccountsLocally(names); val idToFieldsCreated = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, names); val allIds = idToFieldsCreated.keys.toTypedArray(); deleteRecordsLocally(ACCOUNTS_SOUP, *allIds); trySyncUp(3, MergeMode.LEAVE_IF_CHANGED); checkDbDeleted(ACCOUNTS_SOUP, allIds, Constants.ID) }
    @Test fun testSyncUpWithLocallyDeletedRemotelyUpdatedRecordsWithoutOverwrite() { trySyncDown(MergeMode.LEAVE_IF_CHANGED); val allIds = idToFields.keys.toTypedArray(); val idsLocallyDeleted = arrayOf(allIds[0], allIds[1], allIds[2]); deleteRecordsLocally(ACCOUNTS_SOUP, *idsLocallyDeleted); Thread.sleep(1000); val idToFieldsRemotelyUpdated = HashMap<String, Map<String, Any>>(); for (id in idsLocallyDeleted) { idToFieldsRemotelyUpdated[id] = updatedFields(idToFields[id]!!, REMOTELY_UPDATED) }; updateRecordsOnServer(idToFieldsRemotelyUpdated, Constants.ACCOUNT); trySyncUp(3, MergeMode.LEAVE_IF_CHANGED); checkDbStateFlags(idsLocallyDeleted.toList(), false, false, true, ACCOUNTS_SOUP); checkServer(idToFieldsRemotelyUpdated, Constants.ACCOUNT); trySyncUp(3, MergeMode.OVERWRITE); checkDbDeleted(ACCOUNTS_SOUP, idsLocallyDeleted, Constants.ID); checkServerDeleted(idsLocallyDeleted, Constants.ACCOUNT) }
    @Test fun testSyncUpWithLocallyDeletedRemotelyDeletedRecords() { trySyncUpWithLocallyDeletedRemotelyDeletedRecords(MergeMode.OVERWRITE) }
    @Test fun testSyncUpWithLocallyDeletedRemotelyDeletedRecordsWithoutOverwrite() { trySyncUpWithLocallyDeletedRemotelyDeletedRecords(MergeMode.LEAVE_IF_CHANGED) }
    fun trySyncUpWithLocallyDeletedRemotelyDeletedRecords(mergeMode: MergeMode) { trySyncDown(MergeMode.OVERWRITE); val allIds = idToFields.keys.toTypedArray(); val idsLocallyDeleted = arrayOf(allIds[0], allIds[1], allIds[2]); deleteRecordsLocally(ACCOUNTS_SOUP, *idsLocallyDeleted); deleteRecordsByIdOnServer(idToFields.keys, Constants.ACCOUNT); trySyncUp(3, mergeMode); checkDbDeleted(ACCOUNTS_SOUP, idsLocallyDeleted, Constants.ID); checkServerDeleted(idsLocallyDeleted, Constants.ACCOUNT) }
    @Test fun testSyncUpWithLocallyUpdatedRemotelyDeletedRecords() { trySyncDown(MergeMode.OVERWRITE); val idToFieldsLocallyUpdated = makeLocalChanges(idToFields, ACCOUNTS_SOUP); val remotelyDeletedId = idToFieldsLocallyUpdated.keys.toTypedArray()[0]; deleteRecordsByIdOnServer(HashSet(listOf(remotelyDeletedId)), Constants.ACCOUNT); val locallyUpdatedRemotelyDeletedName = idToFieldsLocallyUpdated[remotelyDeletedId]!![Constants.NAME] as String; trySyncUp(3, MergeMode.OVERWRITE); val idToFieldsUpdated = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, getNamesFromIdToFields(idToFieldsLocallyUpdated)); checkDb(idToFieldsUpdated, ACCOUNTS_SOUP); Assert.assertEquals(3, idToFieldsUpdated.size); Assert.assertFalse(idToFieldsUpdated.containsKey(remotelyDeletedId)); for (accountId in idToFieldsUpdated.keys) { val accountName = idToFieldsUpdated[accountId]!![Constants.NAME] as String; if (accountName == locallyUpdatedRemotelyDeletedName) { Assert.assertFalse(idToFields.containsKey(accountId)); idToFields.remove(remotelyDeletedId); idToFields[accountId] = idToFieldsUpdated[accountId]!! } else { Assert.assertTrue(idToFields.containsKey(accountId)) } }; checkServer(idToFieldsUpdated, Constants.ACCOUNT) }
    @Test fun testSyncUpWithLocallyUpdatedRemotelyDeletedRecordsWithoutOverwrite() { trySyncDown(MergeMode.OVERWRITE); val idToFieldsLocallyUpdated = makeLocalChanges(idToFields, ACCOUNTS_SOUP); val remotelyDeletedId = idToFieldsLocallyUpdated.keys.toTypedArray()[0]; deleteRecordsByIdOnServer(HashSet(listOf(remotelyDeletedId)), Constants.ACCOUNT); trySyncUp(3, MergeMode.LEAVE_IF_CHANGED); val idToFieldsUpdated = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, getNamesFromIdToFields(idToFieldsLocallyUpdated)); Assert.assertEquals(3, idToFieldsUpdated.size); Assert.assertTrue(idToFieldsUpdated.containsKey(remotelyDeletedId)); checkDbStateFlags(listOf(remotelyDeletedId), false, true, false, ACCOUNTS_SOUP); val otherIdtoFields = HashMap(idToFieldsLocallyUpdated); otherIdtoFields.remove(remotelyDeletedId); checkDb(otherIdtoFields, ACCOUNTS_SOUP); checkServer(otherIdtoFields, Constants.ACCOUNT); checkServerDeleted(arrayOf(remotelyDeletedId), Constants.ACCOUNT) }
    @Test fun testSyncUpWithCreateAndUpdateFieldList() { trySyncDown(MergeMode.OVERWRITE); val idToFieldsLocallyUpdated = makeLocalChanges(idToFields, ACCOUNTS_SOUP); val namesOfUpdated = getNamesFromIdToFields(idToFieldsLocallyUpdated); val namesOfCreated = arrayOf(createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT), createRecordName(Constants.ACCOUNT)); createAccountsLocally(namesOfCreated); trySyncUp(namesOfCreated.size + namesOfUpdated.size, MergeMode.OVERWRITE, listOf(Constants.NAME), listOf(Constants.DESCRIPTION)); val idToFieldsCreated = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(Constants.NAME, Constants.DESCRIPTION), Constants.NAME, namesOfCreated); checkDbStateFlags(idToFieldsCreated.keys, false, false, false, ACCOUNTS_SOUP); checkDbStateFlags(idToFieldsLocallyUpdated.keys, false, false, false, ACCOUNTS_SOUP); val idToFieldsExpectedOnServer = HashMap<String, Map<String, Any>>(); for (id in idToFieldsCreated.keys) { val expectedFields = HashMap<String, Any>(); expectedFields[Constants.NAME] = idToFieldsCreated[id]!![Constants.NAME]!!; expectedFields[Constants.DESCRIPTION] = JSONObject.NULL; idToFieldsExpectedOnServer[id] = expectedFields }; for (id in idToFieldsLocallyUpdated.keys) { val expectedFields = HashMap<String, Any>(); expectedFields[Constants.NAME] = idToFields[id]!![Constants.NAME]!!; expectedFields[Constants.DESCRIPTION] = idToFieldsLocallyUpdated[id]!![Constants.DESCRIPTION]!!; idToFieldsExpectedOnServer[id] = expectedFields }; checkServer(idToFieldsExpectedOnServer, Constants.ACCOUNT); idToFields.putAll(idToFieldsCreated) }
    @Test fun testSyncUpWithExternalId() { val externalIdFieldName = "Id"; val name1 = createRecordName(Constants.ACCOUNT); val name2 = createRecordName(Constants.ACCOUNT); val name3 = createRecordName(Constants.ACCOUNT); val allIds = idToFields.keys.toTypedArray(); Arrays.sort(allIds); val id1 = allIds[0]; val id2 = allIds[1]; val localAccounts = createAccountsLocally(arrayOf(name1, name2, name3)); localAccounts[0].put(externalIdFieldName, id1); smartStore.upsert(ACCOUNTS_SOUP, localAccounts[0]); localAccounts[1].put(externalIdFieldName, id2); smartStore.upsert(ACCOUNTS_SOUP, localAccounts[1]); localAccounts[2].put(externalIdFieldName, JSONObject.NULL); smartStore.upsert(ACCOUNTS_SOUP, localAccounts[2]); val options = SyncOptions.optionsForSyncUp(listOf(Constants.NAME)); trySyncUp(3, options, null, null, externalIdFieldName); val id3 = getIdToFieldsByName(ACCOUNTS_SOUP, arrayOf(), Constants.NAME, arrayOf(name3)).keys.toTypedArray()[0]; val expectedDbIdToFields = HashMap<String, Map<String, Any>>(); expectedDbIdToFields[id1] = createFieldsMapFromNameDescription(name1, localAccounts[0].getString(Constants.DESCRIPTION)); expectedDbIdToFields[id2] = createFieldsMapFromNameDescription(name2, localAccounts[1].getString(Constants.DESCRIPTION)); expectedDbIdToFields[id3] = createFieldsMapFromNameDescription(name3, localAccounts[2].getString(Constants.DESCRIPTION)); checkDbStateFlags(expectedDbIdToFields.keys, false, false, false, ACCOUNTS_SOUP); checkDb(expectedDbIdToFields, ACCOUNTS_SOUP); val expectedServerIdToFields = HashMap<String, Map<String, Any>>(); expectedServerIdToFields[id1] = createFieldsMapFromNameDescription(name1, idToFields[id1]!![Constants.DESCRIPTION] as String); expectedServerIdToFields[id2] = createFieldsMapFromNameDescription(name2, idToFields[id2]!![Constants.DESCRIPTION] as String); expectedServerIdToFields[id3] = createFieldsMapFromNameDescription(name3, null); checkServer(expectedServerIdToFields, Constants.ACCOUNT); idToFields.putAll(expectedServerIdToFields) }
    @Test fun testSyncUpManyLocallyCreatedRecords() { trySyncUpWithLocallyCreatedRecords(500, MergeMode.OVERWRITE) }

    protected open fun trySyncUp(numberChanges: Int, mergeMode: MergeMode) { trySyncUp(numberChanges, mergeMode, null, null) }
    protected open fun trySyncUp(numberChanges: Int, mergeMode: MergeMode, createFieldlist: List<String>?, updateFieldlist: List<String>?) { val options = SyncOptions.optionsForSyncUp(listOf(Constants.NAME, Constants.DESCRIPTION), mergeMode); trySyncUp(numberChanges, options, createFieldlist, updateFieldlist, null) }
    protected open fun trySyncUp(numberChanges: Int, options: SyncOptions, createFieldlist: List<String>?, updateFieldlist: List<String>?, externalIdFieldName: String?) { trySyncUp(SyncUpTarget(createFieldlist, updateFieldlist, null, null, externalIdFieldName), numberChanges, options, false) }
    protected open fun trySyncDown(mergeMode: MergeMode): Long { return trySyncDown(mergeMode, null) }
    protected open fun trySyncDown(mergeMode: MergeMode, syncName: String?): Long { val target = SoqlSyncDownTarget("SELECT Id, Name, Description, LastModifiedDate FROM Account WHERE Id IN ${makeInClause(idToFields.keys)}"); return trySyncDown(mergeMode, target, ACCOUNTS_SOUP, idToFields.size, 1, syncName) }
}
